  let aS=0,iS=0,wS=0;
  for(const[sX,sY,f,sp,w]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;wS+=w;}
  const act=aS/wS,inh=iS/wS;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
