  const pal=[[5,12,52],[12,45,85],[18,90,120],[25,150,140],[80,185,120],[180,195,70],[230,175,55],[220,130,60],[190,75,70],[140,45,80],[75,25,75],[30,15,60],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=Math.abs(reaction)>0.75?1.2:(Math.abs(reaction)>0.5?1.05:0.95);
